import{_ as t,o,c as d,ag as r}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Admin Dashboard → Overview / Analytics (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/overview-analytics.md","filePath":"modules/admin-dashboard/overview-analytics.md"}'),a={name:"modules/admin-dashboard/overview-analytics.md"};function s(n,e,c,i,l,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="admin-dashboard-→-overview-analytics-deep" tabindex="-1">Admin Dashboard → Overview / Analytics (deep) <a class="header-anchor" href="#admin-dashboard-→-overview-analytics-deep" aria-label="Permalink to &quot;Admin Dashboard → Overview / Analytics (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>overview-analytics</code><br><strong>Route:</strong> <code>/admin-dashboard/overview</code></p><p>This doc describes <strong>every</strong> code file, <strong>every</strong> GraphQL query/typeDef, and <strong>every</strong> resolver involved in the Admin Overview (Analytics) screen, plus how the frontend integrates with the API.</p><hr><h2 id="_1-purpose-and-flow" tabindex="-1">1. Purpose and flow <a class="header-anchor" href="#_1-purpose-and-flow" aria-label="Permalink to &quot;1. Purpose and flow&quot;">​</a></h2><ul><li><strong>Purpose:</strong> Show platform analytics: overall stats (registrations, lessons booked, reviews, attendance) and graphs (active users, revenue per instructor, bookings per instructor, total earnings, conversion rates). Optional filter by date range and by instructor(s).</li><li><strong>Flow:</strong> User opens Overview → frontend sends <code>getAdminAnalytics(filter)</code> and <code>getAllInstructors()</code> → backend computes stats and graph data from DB → UI renders cards and charts (e.g. ApexCharts). Changing filter re-sends <code>getAdminAnalytics</code> with new <code>filter</code>.</li></ul><hr><h2 id="_2-frontend-–-every-file" tabindex="-1">2. Frontend – every file <a class="header-anchor" href="#_2-frontend-–-every-file" aria-label="Permalink to &quot;2. Frontend – every file&quot;">​</a></h2><h3 id="_2-1-page-component" tabindex="-1">2.1 Page component <a class="header-anchor" href="#_2-1-page-component" aria-label="Permalink to &quot;2.1 Page component&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Exports</th><th>Imports (main)</th><th>GraphQL / API</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/adminOverview.tsx</code></td><td>Main Analytics page; filter UI, stats cards, charts</td><td><code>AnalyticsDashboard</code> (named export, used by router)</td><td><code>useQuery</code> (Apollo), <code>GET_ADMIN_ANALYTICS</code>, <code>GET_ALL_INSTRUCTORS</code> from <code>../../../graphql/Queries/AdminContact</code>, <code>FilterType</code>, <code>AnalyticsFilterInput</code>, <code>AdminAnalytics</code>, <code>Instructor</code> from <code>../../../types/AdminContact</code>, <code>format</code> (date-fns), <code>react-apexcharts</code> (dynamic)</td><td>Uses <code>GET_ADMIN_ANALYTICS</code> with variable <code>filter</code> (AnalyticsFilterInput). Uses <code>GET_ALL_INSTRUCTORS</code> (no variables).</td></tr></tbody></table><ul><li><strong>State:</strong> <code>filters</code> (AnalyticsFilterInput), <code>selectedInstructors</code>, <code>dateRange</code>, <code>isFilterOpen</code>, <code>showFromDatePicker</code>, <code>showToDatePicker</code>.</li><li><strong>Queries used:</strong><ul><li><code>useQuery(GET_ADMIN_ANALYTICS, { variables: { filter: filters } })</code> → <code>data.getAdminAnalytics</code> (overallStats, graphData).</li><li><code>useQuery(GET_ALL_INSTRUCTORS)</code> → <code>data.getAllInstructors</code> (list for filter dropdown).</li></ul></li><li><strong>Behavior:</strong> Filter apply/clear updates <code>filters</code> and refetches analytics. Stats and graph data are derived from <code>getAdminAnalytics</code>; instructor list from <code>getAllInstructors</code>.</li></ul><h3 id="_2-2-graphql-operations-frontend" tabindex="-1">2.2 GraphQL operations (frontend) <a class="header-anchor" href="#_2-2-graphql-operations-frontend" aria-label="Permalink to &quot;2.2 GraphQL operations (frontend)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>Frontend/src/graphql/Queries/AdminContact.ts</code></td><td>Defines the two queries used by Overview.</td></tr></tbody></table><p><strong>Query 1: GetAdminAnalytics</strong></p><ul><li><strong>Operation name:</strong> <code>GetAdminAnalytics</code></li><li><strong>Variables:</strong> <code>$filter: AnalyticsFilterInput</code> (optional)</li><li><strong>Requested fields:</strong><ul><li><code>getAdminAnalytics(filter: $filter) { overallStats { totalRegistrations, totalLessonsBooked, reviewsGiven, lessonAttendance, attendanceRate }, graphData { activeUsers { time, students, instructors }, averageRevenuePerInstructor { time, averageRevenue }, bookingsPerInstructor { time, averageBookings }, totalEarnings { time, totalEarnings }, conversionRates { time, visitors, registrations, rate } } }</code></li></ul></li><li><strong>Used in:</strong> <code>adminOverview.tsx</code> (useQuery with <code>variables: { filter: filters }</code>).</li></ul><p><strong>Query 2: GetAllInstructors</strong></p><ul><li><strong>Operation name:</strong> <code>GetAllInstructors</code></li><li><strong>Variables:</strong> none</li><li><strong>Requested fields:</strong> <code>getAllInstructors { _id, firstName, lastName }</code></li><li><strong>Used in:</strong> <code>adminOverview.tsx</code> (useQuery, no variables).</li></ul><h3 id="_2-3-types-frontend" tabindex="-1">2.3 Types (frontend) <a class="header-anchor" href="#_2-3-types-frontend" aria-label="Permalink to &quot;2.3 Types (frontend)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Types / enums used by Overview</th></tr></thead><tbody><tr><td><code>Frontend/src/types/AdminContact.ts</code></td><td>Shared types for admin contact/analytics</td><td><code>FilterType</code> (enum), <code>AnalyticsFilterInput</code>, <code>AdminAnalytics</code>, <code>OverallStats</code>, <code>ActiveUserDataPoint</code>, <code>RevenueDataPoint</code>, <code>BookingDataPoint</code>, <code>EarningDataPoint</code>, <code>ConversionDataPoint</code>, <code>GraphData</code>; <code>Instructor</code> (for dropdown).</td></tr></tbody></table><hr><h2 id="_3-backend-–-typedefs-every-type-and-field" tabindex="-1">3. Backend – TypeDefs (every type and field) <a class="header-anchor" href="#_3-backend-–-typedefs-every-type-and-field" aria-label="Permalink to &quot;3. Backend – TypeDefs (every type and field)&quot;">​</a></h2><p><strong>File:</strong> <code>server/src/graphql/typeDefs/AdminOverallAnalyticsTypes.js</code></p><table tabindex="0"><thead><tr><th>Kind</th><th>Name</th><th>Definition</th></tr></thead><tbody><tr><td>Enum</td><td><code>FilterType</code></td><td><code>LAST_WEEK</code>, <code>THIS_WEEK</code>, <code>LAST_MONTH</code>, <code>THIS_MONTH</code>, <code>LAST_YEAR</code>, <code>THIS_YEAR</code>, <code>LAST_6_MONTHS</code>, <code>CUSTOM</code></td></tr><tr><td>Input</td><td><code>AnalyticsFilterInput</code></td><td><code>instructorIds: [ID]</code>, <code>filterType: FilterType</code>, <code>fromDate: String</code>, <code>toDate: String</code></td></tr><tr><td>Type</td><td><code>OverallStats</code></td><td><code>totalRegistrations: Int</code>, <code>totalLessonsBooked: Int</code>, <code>reviewsGiven: Int</code>, <code>lessonAttendance: Int</code>, <code>attendanceRate: Float</code></td></tr><tr><td>Type</td><td><code>ActiveUserDataPoint</code></td><td><code>time: String</code>, <code>students: Int</code>, <code>instructors: Int</code></td></tr><tr><td>Type</td><td><code>RevenueDataPoint</code></td><td><code>time: String</code>, <code>averageRevenue: Float</code></td></tr><tr><td>Type</td><td><code>BookingDataPoint</code></td><td><code>time: String</code>, <code>averageBookings: Float</code></td></tr><tr><td>Type</td><td><code>EarningDataPoint</code></td><td><code>time: String</code>, <code>totalEarnings: Float</code></td></tr><tr><td>Type</td><td><code>ConversionDataPoint</code></td><td><code>time: String</code>, <code>visitors: Int</code>, <code>registrations: Int</code>, <code>rate: Float</code></td></tr><tr><td>Type</td><td><code>GraphData</code></td><td><code>activeUsers: [ActiveUserDataPoint]</code>, <code>averageRevenuePerInstructor: [RevenueDataPoint]</code>, <code>bookingsPerInstructor: [BookingDataPoint]</code>, <code>totalEarnings: [EarningDataPoint]</code>, <code>conversionRates: [ConversionDataPoint]</code></td></tr><tr><td>Type</td><td><code>AdminAnalytics</code></td><td><code>overallStats: OverallStats</code>, <code>graphData: GraphData</code></td></tr><tr><td>Type</td><td><code>Instructor</code></td><td><code>_id: ID!</code>, <code>firstName: String!</code>, <code>lastName: String!</code></td></tr><tr><td>Query</td><td><code>getAdminAnalytics(filter: AnalyticsFilterInput): AdminAnalytics</code></td><td>Returns analytics for the given filter.</td></tr><tr><td>Query</td><td><code>getAllInstructors: [Instructor!]!</code></td><td>Returns list of instructors (id, firstName, lastName) for filter dropdown.</td></tr></tbody></table><hr><h2 id="_4-backend-–-resolvers-every-function" tabindex="-1">4. Backend – Resolvers (every function) <a class="header-anchor" href="#_4-backend-–-resolvers-every-function" aria-label="Permalink to &quot;4. Backend – Resolvers (every function)&quot;">​</a></h2><p><strong>File:</strong> <code>server/src/graphql/resolvers/AdminAnalytics.resolver.js</code></p><p><strong>Dependencies:</strong> <code>mongoose</code>, <code>dayjs</code>, <code>User</code>, <code>Instructor</code> (from <code>../../models/User</code>), <code>studentBookingModel</code> (from <code>../../models/studentBooking.model</code>), <code>Review</code> (from <code>../../models/Reviews</code>), <code>Visitor</code> (from <code>../../models/Visitors</code>).</p><table tabindex="0"><thead><tr><th>Resolver</th><th>Arguments</th><th>What it does</th><th>Models / services</th></tr></thead><tbody><tr><td><code>Query.getAdminAnalytics</code></td><td><code>(_, { filter })</code></td><td>Reads <code>filter.instructorIds</code>, <code>filterType</code>, <code>fromDate</code>, <code>toDate</code>. Computes date range (from/to) from filterType or custom dates. Builds <code>matchInstructor</code> if instructorIds provided. <strong>Overall stats:</strong> (1) <code>totalRegistrations</code> = User count (Student/Instructor, createdAt in range). (2) <code>totalLessonsBooked</code> = aggregate on studentBookingModel, slots in range, booked, status not cancelled/refund. (3) <code>reviewsGiven</code> = Review count, completed, in range. (4) Attended lessons = slots in range, booked, (status completed or slot end ≤ now). (5) <code>attendanceRate</code> = attended / total booked (capped 100%). <strong>Graph data:</strong> Groups by day/week/month by duration; for each bucket computes activeUsers (unique students/instructors from slots), averageRevenuePerInstructor, bookingsPerInstructor, totalEarnings (delivered slots), conversionRates (visitors vs registrations from Visitor + User). Returns <code>{ overallStats, graphData }</code>.</td><td>User, studentBookingModel, Review, Visitor</td></tr><tr><td><code>Query.getAllInstructors</code></td><td><code>(_, __)</code></td><td>Finds all instructors with projection <code>_id firstName lastName</code>; returns array of <code>{ _id, firstName, lastName }</code>.</td><td>Instructor</td></tr></tbody></table><hr><h2 id="_5-data-flow-step-by-step" tabindex="-1">5. Data flow (step-by-step) <a class="header-anchor" href="#_5-data-flow-step-by-step" aria-label="Permalink to &quot;5. Data flow (step-by-step)&quot;">​</a></h2><ol><li>User navigates to <code>/admin-dashboard/overview</code> → router renders <code>AnalyticsDashboard</code> from <code>adminOverview.tsx</code>.</li><li>Component mounts → <code>useQuery(GET_ADMIN_ANALYTICS, { variables: { filter: filters } })</code> and <code>useQuery(GET_ALL_INSTRUCTORS)</code> run (initial <code>filters</code> may be e.g. <code>{ filterType: &quot;LAST_MONTH&quot; }</code>).</li><li>Apollo sends GraphQL requests to backend: <ul><li><code>Query.getAdminAnalytics(filter)</code> → resolver computes date range, runs User/studentBookingModel/Review/Visitor reads and aggregations, returns <code>AdminAnalytics</code>.</li><li><code>Query.getAllInstructors</code> → resolver returns Instructor list.</li></ul></li><li>Frontend receives <code>getAdminAnalytics</code> and <code>getAllInstructors</code>; renders stats cards from <code>overallStats</code> and charts from <code>graphData</code>; populates filter dropdown from <code>getAllInstructors</code>.</li><li>User changes filter (date range and/or instructors) and applies → <code>filters</code> state updates → <code>GET_ADMIN_ANALYTICS</code> refetches with new <code>filter</code> → resolver runs again with new range/instructorIds → UI updates.</li></ol><hr><h2 id="_6-quick-reference-file-→-role" tabindex="-1">6. Quick reference (file → role) <a class="header-anchor" href="#_6-quick-reference-file-→-role" aria-label="Permalink to &quot;6. Quick reference (file → role)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Role</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/adminOverview.tsx</code></td><td>Analytics page; uses GET_ADMIN_ANALYTICS + GET_ALL_INSTRUCTORS</td></tr><tr><td><code>Frontend/src/graphql/Queries/AdminContact.ts</code></td><td>Defines GET_ADMIN_ANALYTICS, GET_ALL_INSTRUCTORS</td></tr><tr><td><code>Frontend/src/types/AdminContact.ts</code></td><td>FilterType, AnalyticsFilterInput, AdminAnalytics, graph types, Instructor</td></tr><tr><td><code>server/src/graphql/typeDefs/AdminOverallAnalyticsTypes.js</code></td><td>FilterType, AnalyticsFilterInput, AdminAnalytics, GraphData, OverallStats, Instructor, getAdminAnalytics, getAllInstructors</td></tr><tr><td><code>server/src/graphql/resolvers/AdminAnalytics.resolver.js</code></td><td>getAdminAnalytics (stats + graph), getAllInstructors (list for dropdown)</td></tr><tr><td><code>server/src/models/User.js</code> (Instructor)</td><td>getAllInstructors reads from Instructor</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>getAdminAnalytics aggregates bookings/slots</td></tr><tr><td><code>server/src/models/Reviews.js</code></td><td>getAdminAnalytics counts reviews</td></tr><tr><td><code>server/src/models/Visitors.js</code></td><td>getAdminAnalytics conversion buckets</td></tr></tbody></table><hr><p>This is the <strong>deep</strong> doc template: every file, every query, every typeDef field, every resolver. Other admin-dashboard features (admin-access, documents, …) will follow the same structure in their own <code>.md</code> files under <code>docs/modules/admin-dashboard/</code>.</p>',36)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
